#include "../src/game/stage2_boss_sequence.hpp"
#include "../src/game/stage2_projectiles.hpp"
int main(int argc,char**argv){if(argc!=2)return 1;shin::AssetStore a(argv[1]);shin::game::Stage2Boss b(100,100,a);shin::game::Stage2BossSequence s;s.begin_intro(b,100,8,true);s.tick(3280,false,300);if(b.payload.at(0x50)!=8)return 2;s.tick(3281,false,300);if(b.payload.at(0x50)!=9)return 3;s.tick(6290,false,300);if(!s.active())return 4;s.tick(6291,false,300);if(s.active()||b.cinematic||s.restore_player_state!=8||s.camera_restore_callback!=0x427ee0)return 5;s.begin_ending(100,9,false);s.tick(6500,false,300);if(!s.active())return 6;s.tick(6501,false,300);if(!s.completed||s.restore_player_state!=9)return 7;s.begin_ending(100,9,true);s.tick(101,true,300);s.tick(102,false,300);if(s.active())return 8;shin::MapData map{100,100,{}};map.cells.resize(10000,{-1,-1,-1,0,0});shin::AppImage blocks{32,32,std::vector<unsigned char>(1024,0)};shin::game::Stage2Projectiles balls(a,map,blocks);balls.spawn(100,100,4,-16);shin::IndexedSurface f(640,480,254);balls.tick(0,0,f);if(balls.targets[0].at(4)!=104||balls.targets[0].at(8)!=85||balls.targets[0].at(0x40)!=-15)return 9;auto x=balls.targets[0].at(4);balls.tick(2000,0,f);if(balls.targets[0].at(4)!=x)return 10;for(int xx=0;xx<100;++xx)map.cells[10*100+xx].foreground_tile=0;blocks.indices.assign(1024,1);shin::game::Stage2Projectiles bounce(a,map,blocks);bounce.spawn(100,300,0,3);for(int i=0;i<200&&!bounce.targets.empty();++i)bounce.tick(0,0,f);if(!bounce.targets.empty())return 11;b.cinematic=true;b.cinematic_pose(8);for(int i=0;i<22;++i)b.tick(0,0,300,64,a,f);b.cinematic_pose(9);b.tick(0,0,300,64,a,f);return 0;}

